import json
from pathlib import Path
acc = json.loads(Path(\"/workspace/access.json\").read_text())
# print keys only, not secrets
print(acc.keys())
def scrub(o, depth=0):
    if isinstance(o, dict):
        return {k: (\"<redacted>\" if any(s in k.lower() for s in [\"key\",\"token\",\"secret\",\"password\"]) else scrub(v, depth+1)) for k,v in o.items()}
    if isinstance(o, list):
        return [scrub(x, depth+1) for x in o[:20]]
    if isinstance(o, str) and len(o)>80:
        return o[:40]+\"...\"
    return o
print(json.dumps(scrub(acc), indent=2)[:5000])
PY"
